def total_of_tail(values, k):
    # If k is 0, return 0
    if k == 0:
        return 0

    # If k is larger than the list, treat it as the whole list
    if k > len(values):
        k = len(values)

    # Calculate the sum of the last k elements
    return sum(values[-k:])
